import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    n = int(input_data[0])
    k = int(input_data[1])

    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        dp[i] = dp[i - 1] * i

    used = [False] * (n + 1)
    result = []

    def count_permutations(remaining_n, max_val):
        if remaining_n == 0:
            return 1
        cnt = 0
        for length in range(1, remaining_n + 1):
            if length > max_val:
                break
            ways = 1
            for j in range(length - 1):
                ways *= (max_val - j)
            ways *= dp[remaining_n - length]
            cnt += ways
        return cnt

    current_max = 0
    for pos in range(n):
        remaining_n = n - pos
        start = current_max + 1
        while True:
            if start > n:
                break
            length = 1
            while True:
                if length > remaining_n:
                    break
                if start + length - 1 > n:
                    break
                if any(used[start + offset] for offset in range(length)):
                    break

                max_in_cycle = start + length - 1
                available_slots = 0
                temp_used = used[:]
                for i in range(start, start + length):
                    if not temp_used[i]:
                        temp_used[i] = True
                        available_slots += 1

                if available_slots != length:
                    break

                if length == 1:
                    count = dp[remaining_n - 1]
                else:
                    count = dp[remaining_n - length]
                    for j in range(1, length):
                        count *= (n - (start - 1) - j)

                if k <= count:
                    for i in range(start, start + length):
                        used[i] = True
                        result.append(i)
                    current_max = max(current_max, start + length - 1)
                    break
                else:
                    k -= count
                    length += 1
            else:
                continue
            break
        else:
            break

    print(' '.join(map(str, result)))

if __name__ == '__main__':
    main()
